command:
python3 - <<'PY'
path='mux_test.go'
s=open(path).read()
old='''	if _, err := st1.Read(buf); err != nil {
		t.Fatal(err)
	}
	// st1 is still readable/writable? remote FIN received -> write should fail
	if _, err := st1.Write([]byte("y")); err != io.ErrClosedPipe {
		t.Fatalf("write after remote FIN = %v, want io.ErrClosedPipe", err)
	}'''
new='''	if _, err := st1.Read(buf); err != nil {
		t.Fatal(err)
	}
	// Wait until the remote FIN is processed (read returns io.EOF).
	if _, err := st1.Read(buf); err != io.EOF {
		t.Fatalf("read after remote FIN = %v, want io.EOF", err)
	}
	// Remote FIN received -> write should fail
	if _, err := st1.Write([]byte("y")); err != io.ErrClosedPipe {
		t.Fatalf("write after remote FIN = %v, want io.ErrClosedPipe", err)
	}'''
assert old in s
s=s.replace(old,new)
open(path,'w').write(s)
PY
gofmt -w mux_test.go && timeout 25 go test -run 'TestMuxStreamRemoval' -count=1 -v -timeout 20s . 2>&1 | tail -20; echo "EXIT: $?"
